import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

// Create the LocalStorageComponent class here
@Component({
  selector: 'app-local-storage',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div>
      <input type="text" [(ngModel)]="inputValue" placeholder="Enter text to save" />
      <button (click)="saveToLocalStorage()">Save to LocalStorage</button>
      <!-- Add load and clear buttons here -->
    </div>
  `
})
export class LocalStorageComponent {
  inputValue = '';
  storedValue = '';

  saveToLocalStorage() {
    localStorage.setItem('userInput', this.inputValue);
    this.storedValue = this.inputValue;
  }

  loadFromLocalStorage() {
    const value = localStorage.getItem('userInput');
    if (value) {
      this.storedValue = value;
      this.inputValue = value;
    }
  }

  clearLocalStorage() {
    localStorage.removeItem('userInput');
    this.storedValue = '';
    this.inputValue = '';
  }
}

